 private void photo(){try{Bitmap b=Bitmap.createBitmap(scene.getWidth(),scene.getHeight(),Bitmap.Config.ARGB_8888);scene.draw(new Canvas(b));if(android.os.Build.VERSION.SDK_INT>=29){android.content.ContentValues values=new android.content.ContentValues();values.put(android.provider.MediaStore.Images.Media.DISPLAY_NAME,"ForeverPet-"+System.currentTimeMillis()+".png");values.put(android.provider.MediaStore.Images.Media.MIME_TYPE,"image/png");values.put(android.provider.MediaStore.Images.Media.RELATIVE_PATH,"Pictures/My Forever Pet");android.net.Uri uri=getContentResolver().insert(android.provider.MediaStore.Images.Media.EXTERNAL_CONTENT_URI,values);if(uri==null)throw new java.io.IOException("Photo destination unavailable");try(java.io.OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null||!b.compress(Bitmap.CompressFormat.PNG,100,out))throw new java.io.IOException("Photo save failed");}catch(java.io.IOException e){getContentResolver().delete(uri,null,null);throw e;}Toast.makeText(this,"Photo saved to Pictures/My Forever Pet",0).show();}else Toast.makeText(this,"Photo saving needs Android 10 or later",0).show();b.recycle();}catch(Exception e){Toast.makeText(this,"Could not save photo",0).show();}}
 private int hitHome(MotionEvent e){return art.homeHit(state(),e.getX()*160/Math.max(1,scene.getWidth()),e.getY()*192/Math.max(1,scene.getHeight()),scene.getWidth(),scene.getHeight());}
 private void homeTouch(MotionEvent e){switch(hitHome(e)){case HomeLayout.PET:roomAction(15,0,3);break;case HomeLayout.BED:roomAction(36,0,3);break;case HomeLayout.BOWL:feedMenu();break;case HomeLayout.BALL:roomAction(34,0,4);break;case HomeLayout.CONSOLE:chooseGame();break;case HomeLayout.LAB:room=5;rebuild();break;default:if(e.getY()>scene.getHeight()*.89f&&state().waste>0)roomAction(3,0,3);}}
 private android.graphics.drawable.GradientDrawable panel(int color,int stroke,int radius){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(color);d.setStroke(dp(1),stroke);d.setCornerRadius(dp(radius));return d;}
 private TextView label(String value,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setIncludeFontPadding(false);if(bold)t.setTypeface(Typeface.create("sans-serif-medium",0));return t;}
 private ProgressBar meter(int color){ProgressBar b=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);b.setMax(100);b.setProgressTintList(android.content.res.ColorStateList.valueOf(color));b.setProgressBackgroundTintList(android.content.res.ColorStateList.valueOf(0xff3c405d));android.graphics.drawable.GradientDrawable track=panel(0xff19182e,0xff69638e,5);android.graphics.drawable.GradientDrawable fill=gloss(color,blend(color,0xff433064,.32f),color,5);android.graphics.drawable.ClipDrawable clip=new android.graphics.drawable.ClipDrawable(fill,Gravity.LEFT,android.graphics.drawable.ClipDrawable.HORIZONTAL);android.graphics.drawable.LayerDrawable layers=new android.graphics.drawable.LayerDrawable(new android.graphics.drawable.Drawable[]{track,clip});layers.setId(0,android.R.id.background);layers.setId(1,android.R.id.progress);b.setProgressDrawable(layers);b.setProgressTintList(null);b.setProgressBackgroundTintList(null);return b;}
 private int blend(int a,int b,float k){return Color.rgb((int)(Color.red(a)*(1-k)+Color.red(b)*k),(int)(Color.green(a)*(1-k)+Color.green(b)*k),(int)(Color.blue(a)*(1-k)+Color.blue(b)*k));}
 private void details(){PetState s=state();dialog().setTitle(s.displayName()+" • Profile").setMessage(s.stageName()+" · Generation "+s.generation+" · "+s.fieldName()+"\nLevel "+s.level()+" · XP "+s.xp+"\nHunger "+s.hunger+"/5 · Mood "+s.happy+"/10\nEnergy "+s.energy+"% · Bond "+s.bond+"/100\nCare misses "+s.mistakes+" · Waste "+s.waste+"\n"+s.personality()+"\nHygiene "+s.hygiene+"% · Toilet "+s.toilet+"%\n"+s.growth()).setPositiveButton("Close",null).setNeutralButton("Rename",(d,i)->rename()).show();}
 private void feedMenu(){menu("Choose food • "+state().hungerHint(),new String[]{"Meat • 4 coins","Carrot • 2 coins","Fish • 3 coins","Grain • Free"},i->{PetState s=state();if(s.hunger>=5){Toast.makeText(this,"Your pet is full",0).show();return;}act(14,i);});}
 private void rooms(){menu("Your home",new String[]{"Kitchen","Bathroom","Bedroom","Playroom","Garden","Potion lab","Home"},i->{room=i<6?i:-1;zoom=2;expandedScene=false;rebuild();});}
 private void quietScrub(){if(pet.action(29,0)){cached=null;reaction=2;reactionUntil=SystemClock.elapsedRealtime()+700;update();}}
 private void roomAction(int a,int v,int effect){boolean ok=pet.action(a,v);cached=null;if(ok){reaction=effect;reactionUntil=SystemClock.elapsedRealtime()+1800;scene.performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);update();}else Toast.makeText(this,"Not needed, not ready, or missing supplies",Toast.LENGTH_SHORT).show();}
 private void roomTouch(float x,float y){if(x<0||x>160||y<0||y>192)return;if(room==0){if(y>140&&x<55)feedMenu();else if(y>140&&x>105)roomAction(27,0,1);else if(y>60&&y<140)roomAction(15,0,3);}
 else if(room==1){if(y>140&&x<55)roomAction(29,0,2);else if(y>140&&x>105)roomAction(30,0,2);else if(x>115&&y<115)roomAction(31,0,3);else quietScrub();}
 else if(room==2){if(x>115&&y<90)roomAction(36,0,3);else if(y>65&&y<155)roomAction(36,0,3);}
 else if(room==3){if(y>130)roomAction(34,x<55?0:x<105?1:2,4);else if(y>50)roomAction(15,0,3);}
 else if(room==4){if(y>90)roomAction(state().gardenAt==0?32:33,0,4);}
 else if(room==5){if(y>125&&x<80)roomAction(28,0,3);else if(y>125)roomAction(26,0,3);}}
 private void talk(){if(!state().available()){Toast.makeText(this,"Your pet is resting or away",0).show();return;}if(voice.busy()){voice.cancel();caption.setText("Voice stopped");return;}if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},42);return;}dialog().setTitle("Talk to your pet").setMessage("Record up to 3 seconds, then hear your pet repeat it in a funny voice. Audio stays in memory on this device and is discarded after playback.").setPositiveButton("Record",(d,i)->{if(!active)return;voice.start(state().species()%3,phase->h.post(()->{if(!active)return;if(phase==1){caption.setText("Listening…");}else if(phase==2){reaction=3;reactionUntil=SystemClock.elapsedRealtime()+3000;caption.setText("Your pet is talking!");}else if(phase<0)Toast.makeText(this,"Microphone or playback unavailable",0).show();else update();}));}).setNegativeButton("Cancel",null).show();}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==42&&active){if(results.length>0&&results[0]==android.content.pm.PackageManager.PERMISSION_GRANTED)talk();else Toast.makeText(this,"Microphone is optional. You can still play normally.",0).show();}}
