 private AlertDialog.Builder dialog(){return new AlertDialog.Builder(this,android.R.style.Theme_Material_Dialog_Alert);}
 private void menu(String title,String[] options,java.util.function.IntConsumer callback){Dialog d=new Dialog(this);d.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout panel=new LinearLayout(this);panel.setOrientation(1);panel.setPadding(dp(15),dp(16),dp(15),dp(10));panel.setBackground(gloss(0xff4a3c72,0xff242341,0xffb3a6e7,20));TextView heading=label(title,20,0xffffecd2,true);heading.setPadding(dp(4),0,dp(4),dp(10));panel.addView(heading);ScrollView sc=new ScrollView(this);sc.setFillViewport(false);LinearLayout list=new LinearLayout(this);list.setOrientation(1);sc.addView(list);int max=(int)(getResources().getDisplayMetrics().heightPixels*.58);panel.addView(sc,new LinearLayout.LayoutParams(-1,Math.min(max,dp(options.length*56+8))));for(int i=0;i<options.length;i++){final int n=i;LinearLayout row=new LinearLayout(this);button(row,options[i],()->{d.dismiss();callback.accept(n);});list.addView(row);}LinearLayout bottom=new LinearLayout(this);button(bottom,"Close",()->d.dismiss());panel.addView(bottom);d.setContentView(panel);d.show();Window w=d.getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.setLayout((int)(getResources().getDisplayMetrics().widthPixels*.92),-2);}}
 private void rename(){EditText name=new EditText(new ContextThemeWrapper(this,android.R.style.Theme_Material));name.setSingleLine(true);name.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(20)});name.setText(state().nickname);dialog().setTitle("Name your pet").setView(name).setPositiveButton("Save",(d,i)->{pet.rename(name.getText().toString());cached=null;update();}).setNegativeButton("Cancel",null).show();}
 private void updateClock(){long now=System.currentTimeMillis();java.util.TimeZone zone=java.util.TimeZone.getDefault();String key=now/60000+":"+zone.getID()+":"+zone.getOffset(now)+":"+android.text.format.DateFormat.is24HourFormat(this);if(key.equals(clockKey))return;clockKey=key;java.util.Date date=new java.util.Date(now);java.text.DateFormat time=android.text.format.DateFormat.getTimeFormat(this);time.setTimeZone(zone);java.text.DateFormat day=java.text.DateFormat.getDateInstance(java.text.DateFormat.MEDIUM);day.setTimeZone(zone);String weekday=new java.text.SimpleDateFormat("EEE",java.util.Locale.getDefault()).format(date);clockLabel.setText(time.format(date)+" · "+new java.text.SimpleDateFormat("EEE d MMM",java.util.Locale.getDefault()).format(date)+" · "+PetState.dayPhase(PetState.localMinute(now,zone)));}
