 private void collection(PetState p){ScrollView scroll=new ScrollView(this);LinearLayout grid=new LinearLayout(this);grid.setOrientation(1);grid.setBackgroundColor(0xff242447);scroll.addView(grid);for(int i=0;i<PetState.SPECIES.length;i+=3){LinearLayout row=new LinearLayout(this);grid.addView(row);for(int j=i;j<i+3;j++){PetState preview=new PetState();preview.stage=4;preview.field=(j%12)/4;preview.body=j%4;preview.variant=j/12;boolean found=(p.collection&(1<<j))!=0;LinearLayout tile=new LinearLayout(this);tile.setOrientation(1);tile.setGravity(17);tile.setPadding(dp(4),dp(8),dp(4),dp(8));ImageView im=new ImageView(this);im.setImageBitmap(found?art.creatureIcon(preview):art.silhouette(preview));tile.addView(im,new LinearLayout.LayoutParams(dp(64),dp(64)));TextView label=new TextView(this);label.setGravity(Gravity.CENTER);label.setText(found?PetState.SPECIES[j]:"???");final int species=j;tile.setOnClickListener(v->menu(PetState.SPECIES[species],new String[]{p.unlockHint(species)},i2->{}));label.setTextColor(0xfff6eaff);label.setTextSize(11);tile.addView(label);row.addView(tile,new LinearLayout.LayoutParams(0,-2,1));}}panelDialog("Petpedia • "+Integer.bitCount(p.collection)+"/"+PetState.SPECIES.length+" · Tap for unlock hints",scroll);}
