 private void wardrobe(){PetState s=state();ScrollView scroll=new ScrollView(this);LinearLayout list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list);ImageView preview=new ImageView(this);preview.setImageBitmap(art.creatureIcon(s));list.addView(preview,new LinearLayout.LayoutParams(-1,dp(130)));for(int i=0;i<PetState.CLOTHES.length;i+=2){LinearLayout row=new LinearLayout(this);list.addView(row);for(int j=i;j<Math.min(i+2,PetState.CLOTHES.length);j++){final int item=j;LinearLayout tile=new LinearLayout(this);tile.setOrientation(1);tile.setGravity(Gravity.CENTER);tile.setPadding(dp(3),dp(5),dp(3),dp(5));tile.setBackground(gloss(0xff3f4877,0xff242b49,0xff819dd0,12));ImageView im=new ImageView(this);im.setImageBitmap(art.clothesIcon(item));tile.addView(im,new LinearLayout.LayoutParams(dp(70),dp(70)));TextView name=label(PetState.CLOTHES[item],12,0xfff3efff,true);name.setGravity(Gravity.CENTER);tile.addView(name);Button buy=new Button(this);buy.setAllCaps(false);buy.setText(s.ownsClothes(item)?s.worn(PetState.SLOT[item])==item+1?"Remove":"Equip":"Buy "+PetState.COST[item]);buy.setTextColor(0xffffe6b9);buy.setBackground(gloss(0xff59638a,0xff2b3155,0xff92a8d5,8));buy.setOnClickListener(v->{if(pet.action(s.ownsClothes(item)?38:37,item)){cached=null;PetState n=state();preview.setImageBitmap(art.creatureIcon(n));buy.setText(n.worn(PetState.SLOT[item])==item+1?"Remove":"Equip");update();((Dialog)tile.getTag()).dismiss();wardrobe();}else Toast.makeText(this,"Not enough coins or unavailable",0).show();});tile.addView(buy,new LinearLayout.LayoutParams(-1,dp(42)));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(dp(3),dp(3),dp(3),dp(3));row.addView(tile,lp);}}Dialog d=new Dialog(this);d.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout outer=new LinearLayout(this);outer.setOrientation(1);outer.setPadding(dp(10),dp(10),dp(10),dp(6));outer.setBackground(gloss(0xff414b77,0xff1e253f,0xffa0b6e9,17));outer.addView(label("Wardrobe · "+s.coins+" coins",18,0xffffe6b9,true));outer.addView(scroll,new LinearLayout.LayoutParams(-1,(int)(getResources().getDisplayMetrics().heightPixels*.68)));for(int k=1;k<list.getChildCount();k++){LinearLayout row=(LinearLayout)list.getChildAt(k);for(int j=0;j<row.getChildCount();j++)row.getChildAt(j).setTag(d);}LinearLayout close=new LinearLayout(this);button(close,"Close",()->d.dismiss());outer.addView(close);d.setContentView(outer);d.show();d.getWindow().setBackgroundDrawableResource(android.R.color.transparent);d.getWindow().setLayout((int)(getResources().getDisplayMetrics().widthPixels*.95),-2);}
 private void shop(boolean bag){PetState p=pet.snapshot();LinearLayout list=new LinearLayout(this);list.setOrientation(1);list.setPadding(dp(12),dp(8),dp(12),dp(8));list.setBackgroundColor(0xff242447);ScrollView sc=new ScrollView(this);sc.addView(list);AlertDialog dlg=dialog().setTitle(bag?"Inventory":"Shop • "+p.coins+" coins").setView(sc).setNegativeButton("Close",null).create();
 for(int i=0;i<PetState.ITEMS.length;i++){final int item=i;boolean own=(p.owned&(1<<i))!=0;if(bag&&!own)continue;LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(6),dp(4),dp(6),dp(4));ImageView icon=new ImageView(this);icon.setImageBitmap(art.itemIcon(i));icon.setScaleType(ImageView.ScaleType.FIT_CENTER);row.addView(icon,new LinearLayout.LayoutParams(dp(52),dp(52)));TextView name=new TextView(this);name.setText(PetState.ITEMS[i]+"\n"+(own?"Owned":PetState.PRICES[i]+" coins"));name.setTextColor(0xfff8edff);name.setTextSize(14);row.addView(name,new LinearLayout.LayoutParams(0,-2,1));Button buy=new Button(this);buy.setText(bag?(p.equipped==i+1||p.installation==i+1?"Active":"Use"):own?"Owned":"Buy");buy.setEnabled(bag||!own);buy.setOnClickListener(v->{if(!bag&&pet.snapshot().coins<PetState.PRICES[item]){Toast.makeText(this,"Not enough coins",0).show();return;}act(bag?11:10,item);dlg.dismiss();shop(bag);});row.addView(buy,new LinearLayout.LayoutParams(dp(76),dp(48)));list.addView(row);}
 if(bag&&p.owned==0){TextView empty=new TextView(this);empty.setText("Your bag is empty. Visit the shop.");empty.setTextColor(0xfff8edff);list.addView(empty);}dlg.show();}
