 private void rebuild(){dragFood=-1;cached=null;zooms.setVisibility(View.GONE);hud.setVisibility(playing||expandedScene?View.GONE:View.VISIBLE);top.setVisibility(playing||expandedScene?View.GONE:View.VISIBLE);footer.setVisibility(View.GONE);mainNav.removeAllViews();mainNav.setVisibility(playing||expandedScene?View.GONE:View.VISIBLE);leftRail.setVisibility(!playing&&zoom==2&&room<0&&!expandedScene&&state().stage!=PetState.EGG?View.VISIBLE:View.GONE);rightRail.setVisibility(!playing&&zoom==2&&room<0&&state().stage!=PetState.EGG?View.VISIBLE:View.GONE);if(!playing&&!expandedScene&&state().stage!=PetState.EGG){LinearLayout q=new LinearLayout(this);q.setPadding(dp(3),0,dp(3),0);mainNav.addView(q);nav(q,"Feed",0,()->feedMenu());nav(q,"Care",1,()->care());nav(q,"Arcade",2,()->chooseGame());nav(q,"Rooms",3,()->rooms());nav(q,"Lab",4,()->lab());nav(q,"Journal",5,()->journal());nav(q,"World",6,()->world());}actions.removeAllViews();LinearLayout r=new LinearLayout(this);actions.addView(r);PetState s=pet.snapshot();displayedStage=s.stage;if(playing){if(game!=null&&game.mode==Arcade.FIND)button(r,"Zoom / overview",()->{game.zoomSearch();scene.invalidate();});button(r,"Exit & collect",()->finishGame());}
 else if(s.stage==0){button(r,"Hatch egg",()->{pet.action(0,0);rebuild();});button(r,"Land",()->act(6,0));button(r,"Water",()->act(6,1));button(r,"Sky",()->act(6,2));}
 else if(room>=0){button(r,"Back",()->{room=-1;rebuild();});if(room==0){button(r,"Food",()->feedMenu());button(r,"Supplies",()->supplies());}else if(room==1){button(r,"Soap",()->roomAction(29,0,2));button(r,"Rinse",()->roomAction(30,0,2));button(r,"Toilet",()->roomAction(31,0,3));}else if(room==2){button(r,"Lamp",()->roomAction(36,0,3));button(r,"Decor",()->menu("Room theme",new String[]{"Cozy","Ocean • Lv 2","Starlight • Lv 3"},i->roomAction(35,i,3)));}else if(room==3){button(r,"Arcade",()->chooseGame());button(r,"Toys",()->roomAction(34,0,4));button(r,"Talk",()->talk());}else if(room==4){button(r,"Plant / harvest",()->roomAction(state().gardenAt==0?32:33,0,4));}else{button(r,"Medicine",()->roomAction(28,0,3));button(r,"Supplies",()->supplies());}}
 else if(zoom==0){button(r,"Missions",()->space());button(r,"Visit field",()->{zoom=1;rebuild();});button(r,"Home",()->{zoom=2;rebuild();});}
 else if(zoom==1){button(r,"Clean field",()->act(3,0));button(r,"Habitat",()->menu("Habitat",new String[]{"Land","Water","Sky"},i->act(6,i)));button(r,"Home",()->{zoom=2;rebuild();});}
 else if(zoom==2){actions.removeView(r); if(s.stage==PetState.ADULT){LinearLayout social=new LinearLayout(this);actions.addView(social);button(social,"Playdate",()->{act(8,0);rebuild();});button(social,"Breed",()->{PetState p=pet.snapshot();if(p.friendship<4){Toast.makeText(this,"Friendship must reach 4",0).show();return;}dialog().setTitle("Start a new generation?").setMessage("Your pet's next egg inherits the local partner's eye and color traits.").setNegativeButton("Cancel",null).setPositiveButton("Accept",(d,i)->{pet.action(9,0);rebuild();}).show();});}}
 else {button(r,"Home",()->{zoom=2;rebuild();});button(r,"Inspect cells",()->{act(5,0);rebuild();});button(r,"Treat",()->{if(pet.snapshot().sick)act(4,0);else Toast.makeText(this,"No sick cells detected",0).show();});}update();}
 private void chooseGame(){PetState s=state();if(s.sleeping()||s.exploring()||s.energy<5){Toast.makeText(this,"Your pet needs rest or is busy",0).show();return;}menu("PET ARCADE",new String[]{"Star Catch","Flappy Pet","Cloud Jump","Find My Pet","Pet Dash"},i->{game=new Arcade(i,SystemClock.elapsedRealtime());playing=true;frameAt=SystemClock.elapsedRealtime();accum=0;rebuild();});}
 private void care(){PetState s=pet.snapshot();menu("Care & bond",new String[]{"Pet / cuddle","Play together","Train","Clean habitat","Treat cells",s.sleeping()?"Wake up (15 min at night)":"Take a nap (30 min)","Cook meal (2 materials)","Give a bath","Praise / talk","Rename pet","Voice echo"},i->{if(i<3)act(15,i);else if(i==3)act(3,0);else if(i==4){room=-1;zoom=3;rebuild();}else if(i==5)act(16,0);else if(i==6)act(23,0);else if(i==7)act(24,0);else if(i==8)act(15,3);else if(i==9)rename();else talk();});}
