 private void quests(){PetState s=pet.snapshot();String[] q={"Bond with your pet","Clean habitat","Finish an expedition"};for(int i=0;i<3;i++)q[i]+=((s.claimedQuests&(1<<i))!=0?" • Claimed":(s.quests&(1<<i))!=0?" • Claim 15 coins":" • In progress");menu("Care quests",q,i->act(20,i));}
 private String roomCaption(PetState s){if(voice.busy())return voice.phase()==1?"Listening… tap Talk to stop":"Your pet is talking!";switch(room){case 0:return "Drag food to your pet • Snacks: "+s.snacks;case 1:return "Hygiene "+s.hygiene+"% · Toilet "+s.toilet+"% · Soap "+s.soap+"/3";case 2:return s.sleeping()?"Shhh… sleeping":"Tap the lamp to rest";case 3:return "Tap a toy to play together";case 4:return s.gardenAt==0?"Plant a seed for 5 coins":s.clockNow>=s.gardenAt?"Berries ready to harvest!":"Growing • "+Math.max(1,(s.gardenAt-s.clockNow+59999)/60000)+" min";default:return "Medicine: "+s.medicine+" • "+(s.sick?"Needs treatment":"Healthy");}}
 private void finishGame(){if(!playing)return;int reward=game==null?0:game.claim();playing=false;game=null;pet.action(13,reward);rebuild();Toast.makeText(this,"+"+reward+" coins",0).show();}
 private void update(){PetState s=state();if(!playing&&s.stage!=displayedStage){rebuild();return;}String key=s.displayName()+s.stage+s.field+s.generation+s.coins+s.level()+":"+s.hunger+":"+s.happy+":"+s.energy+":"+s.bond+":"+s.crystals+":"+s.wardrobeOwned+":"+s.hat+":"+s.glasses+":"+s.outfit+":"+s.shoes+s.growth();if(!key.equals(lastHud)){lastHud=key;petName.setText(s.nickname.isEmpty()?(s.stage==PetState.EGG?"New Egg":s.stage==PetState.BABY?"Little "+PetState.SPECIES[s.field*4]:s.creature()):s.nickname);petMeta.setText(s.stageName()+" · "+s.fieldName()+" · Lv "+s.level());coinLabel.setText(""+s.coins);crystalLabel.setText(""+s.crystals);String pk=s.stage+":"+s.species()+":"+s.color+":"+s.equipped+":"+s.eyes+":"+s.sick+":"+s.hat+":"+s.glasses+":"+s.outfit+":"+s.shoes;if(!portraitKey.equals(pk)){portraitKey=pk;portrait.setImageBitmap(art.creatureIcon(s));}int[] nums={s.hunger*20,s.happy*10,s.energy,s.bond};String[] v={"Food "+s.hunger+"/5","Mood "+s.happy+"/10","Energy "+s.energy+"%","Bond "+s.bond};for(int i=0;i<4;i++){bars[i].setProgress(nums[i]);values[i].setText(v[i]);}growthLabel.setText(s.growth());growthBar.setProgress(s.growthPercent());}caption.setText(voice.busy()?(voice.phase()==1?"Listening…":"Your pet is talking!"):playing?"Ready to play":s.stage==0?"Tap your egg to begin":room>=0?roomCaption(s):zoom==3?(s.sick?"Tap to remove "+s.germs+" sick cells":s.stage==PetState.BABY?(s.nextCell()>0?"Next field cell in "+(s.nextCell()/60)+":"+(s.nextCell()%60<10?"0":"")+(s.nextCell()%60):"4 cells ready — tap to evolve"):"Diet and care record"):s.sleeping()?(s.sleepUntil>s.clockNow?"Your pet is napping":"Sleeping until 7 AM • tap clock for options"):s.exploring()?"Your pet is exploring":s.pendingCoins>0?"Adventure rewards ready in Journal":s.sick?"Your pet needs treatment in Cell":s.stage==PetState.ADULT&&s.friendship>0?"Friendship "+s.friendship+"/4":s.needs().equals("Feeling good")?s.hungerHint():s.needs());scene.invalidate();}
 @Override protected void onStart(){super.onStart();active=true;cached=null;clockKey="";h.post(refresh);}
 @Override protected void onStop(){active=false;voice.cancel();h.removeCallbacks(refresh);if(playing)finishGame();pet.flush();super.onStop();}
